 '.sz .row{grid-template-columns:32px 1fr 46px;min-height:21px;font-size:9.4px}.pad{padding:9px 11px;display:flex;flex-direction:column;gap:8px}.kv3{display:grid;grid-template-columns:1fr 1fr;gap:8px}'
